<?php require '../config.php'; admin_only(); $msg='';
if(isset($_POST['add'])) { $name=trim($_POST['name']); $email=trim($_POST['email']); $mobile='0000000000';$hash=password_hash(bin2hex(random_bytes(8)),PASSWORD_DEFAULT);$course=trim($_POST['course']);$year=1;$gender='Prefer not to say';$s=$conn->prepare("INSERT INTO students(name,email,mobile,password_hash,course,year,gender,role) VALUES(?,?,?,?,?,?,?,'student')");$s->bind_param('sssssis',$name,$email,$mobile,$hash,$course,$year,$gender);$msg=$s->execute()?'Student added.':'Could not add student (email may already exist).'; }
if(isset($_GET['delete'])) { $id=(int)$_GET['delete'];$s=$conn->prepare("DELETE FROM students WHERE student_id=? AND role='student'");$s->bind_param('i',$id);$s->execute();$msg='Delete request completed.'; }
$q='%'.($_GET['q']??'').'%';$s=$conn->prepare('SELECT student_id,name,email,course FROM students WHERE name LIKE ? OR email LIKE ? ORDER BY student_id DESC');$s->bind_param('ss',$q,$q);$s->execute();$rows=$s->get_result();
?><h2>Practical 11: Student CRUD</h2><p><?=h($msg)?></p><form><input name="q" placeholder="Search name/email"><button>Search</button></form><h3>Add student</h3><form method="post"><input name="name" placeholder="Name" required><input name="email" type="email" placeholder="Email" required><input name="course" placeholder="Course" required><button name="add">Add</button></form><table border="1" cellpadding="6"><tr><th>Name</th><th>Email</th><th>Course</th><th>Delete</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=h($r['name'])?></td><td><?=h($r['email'])?></td><td><?=h($r['course'])?></td><td><a onclick="return confirm('Delete this student?')" href="?delete=<?=$r['student_id']?>">Delete</a></td></tr><?php endwhile;?></table>